# ---------------------------------------------------------------------------
# Data classes
# ---------------------------------------------------------------------------

@dataclass
class Session:
    """Represents a user session stored in PG."""
    session_id: str
    user_id: str
    username: str
    node_id: str
    created_at: float
    expires_at: float
    last_seen: float
    ws_connected: bool = False
    metadata: str = "{}"

    def is_expired(self) -> bool:
        return time.time() > self.expires_at

    def to_dict(self) -> Dict[str, Any]:
        d = asdict(self)
        d["metadata"] = json.loads(d["metadata"]) if d["metadata"] else {}
        d["online"] = self.ws_connected and not self.is_expired()
        return d


# ---------------------------------------------------------------------------
# PgSessionStore — replaces SQLite session storage
# ---------------------------------------------------------------------------

class PgSessionStore:
    """
    PostgreSQL-backed session store.

    Schema (created automatically):
        mesh_sessions (
            session_id   TEXT PRIMARY KEY,
            user_id      TEXT NOT NULL,
            username     TEXT NOT NULL,
            node_id      TEXT NOT NULL,
            created_at   DOUBLE PRECISION NOT NULL,
            expires_at   DOUBLE PRECISION NOT NULL,
            last_seen    DOUBLE PRECISION NOT NULL,
            ws_connected BOOLEAN NOT NULL DEFAULT FALSE,
            metadata     JSONB NOT NULL DEFAULT '{}'::jsonb
        )
        mesh_users (
            user_id    TEXT PRIMARY KEY,
            username   TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            created_at DOUBLE PRECISION NOT NULL
        )
    """

    SCHEMA_SQL = """
    CREATE TABLE IF NOT EXISTS mesh_users (
        user_id        TEXT PRIMARY KEY,
        username       TEXT UNIQUE NOT NULL,
        password_hash  TEXT NOT NULL,
        created_at     DOUBLE PRECISION NOT NULL
    );

    CREATE TABLE IF NOT EXISTS mesh_sessions (
        session_id     TEXT PRIMARY KEY,
        user_id        TEXT NOT NULL REFERENCES mesh_users(user_id) ON DELETE CASCADE,
        username       TEXT NOT NULL,
        node_id        TEXT NOT NULL,
        created_at     DOUBLE PRECISION NOT NULL,
        expires_at     DOUBLE PRECISION NOT NULL,
        last_seen      DOUBLE PRECISION NOT NULL,
        ws_connected   BOOLEAN NOT NULL DEFAULT FALSE,
        metadata       JSONB NOT NULL DEFAULT '{}'::jsonb
    );

    CREATE INDEX IF NOT EXISTS idx_sessions_user_id    ON mesh_sessions(user_id);
    CREATE INDEX IF NOT EXISTS idx_sessions_node_id    ON mesh_sessions(node_id);
    CREATE INDEX IF NOT EXISTS idx_sessions_expires_at ON mesh_sessions(expires_at);
    CREATE INDEX IF NOT EXISTS idx_sessions_ws_connected ON mesh_sessions(ws_connected);

    CREATE TABLE IF NOT EXISTS mesh_node_heartbeats (
        node_id     TEXT PRIMARY KEY,
        last_heartbeat DOUBLE PRECISION NOT NULL,
        metadata    JSONB NOT NULL DEFAULT '{}'::jsonb
    );
    """

    def __init__(self, dsn: str, node_id: str):
        self.dsn = dsn
        self.node_id = node_id
        self.pool: Optional[asyncpg.Pool] = None

    async def connect(self) -> None:
        """Create connection pool and ensure schema exists."""
        self.pool = await asyncpg.create_pool(
            self.dsn,
            min_size=2,
            max_size=10,
            command_timeout=30,
        )
        async with self.pool.acquire() as conn:
            await conn.execute(self.SCHEMA_SQL)
        log.info("PgSessionStore connected to %s (node=%s)", self.dsn, self.node_id)

    async def close(self) -> None:
        if self.pool:
            await self.pool.close()
            self.pool = None
        log.info("PgSessionStore closed")

    # -- User management --------------------------------------------------

    async def create_user(self, username: str, password: str) -> str:
        """Create a user in mesh_users. Returns user_id."""
        user_id = str(uuid.uuid4())
        pw_hash = self._hash_password(password)
        async with self.pool.acquire() as conn:
            try:
                await conn.execute(
                    "INSERT INTO mesh_users (user_id, username, password_hash, created_at) "
                    "VALUES ($1, $2, $3, $4)",
                    user_id, username, pw_hash, time.time(),
                )
            except asyncpg.UniqueViolationError:
                raise ValueError(f"Username '{username}' already exists")
        log.info("Created user '%s' (id=%s)", username, user_id)
        return user_id

    async def verify_user(self, username: str, password: str) -> Optional[str]:
        """Verify credentials. Returns user_id if valid, None otherwise."""
        async with self.pool.acquire() as conn:
            row = await conn.fetchrow(
                "SELECT user_id, password_hash FROM mesh_users WHERE username = $1",
                username,
            )
        if not row:
            return None
        if not self._verify_password(password, row["password_hash"]):
            return None
        return row["user_id"]

    async def get_user(self, user_id: str) -> Optional[Dict[str, Any]]:
        async with self.pool.acquire() as conn:
            row = await conn.fetchrow(
                "SELECT user_id, username, created_at FROM mesh_users WHERE user_id = $1",
                user_id,
            )
        if not row:
            return None
        return dict(row)

    # -- Session management -----------------------------------------------

    async def create_session(
        self,
        user_id: str,
        username: str,
        ttl: int = SESSION_TTL,
        metadata: Optional[Dict] = None,
    ) -> Session:
        """Create a new session in PG. Visible mesh-wide."""
        session_id = secrets.token_urlsafe(32)
        now = time.time()
        session = Session(
            session_id=session_id,
            user_id=user_id,
            username=username,
            node_id=self.node_id,
            created_at=now,
            expires_at=now + ttl,
            last_seen=now,
            ws_connected=False,
            metadata=json.dumps(metadata or {}),
        )
        async with self.pool.acquire() as conn:
            await conn.execute(
                "INSERT INTO mesh_sessions "
                "(session_id, user_id, username, node_id, created_at, expires_at, "
                " last_seen, ws_connected, metadata) "
                "VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9::jsonb)",
                session.session_id, session.user_id, session.username,
                session.node_id, session.created_at, session.expires_at,
                session.last_seen, session.ws_connected, session.metadata,
            )
        log.info("Created session %s for user '%s' on node '%s'",
                 session_id[:12], username, self.node_id)
        return session

    async def get_session(self, session_id: str) -> Optional[Session]:
        """Fetch a session by ID from PG."""
        async with self.pool.acquire() as conn:
            row = await conn.fetchrow(
                "SELECT session_id, user_id, username, node_id, created_at, "
                "       expires_at, last_seen, ws_connected, metadata::text "
                "FROM mesh_sessions WHERE session_id = $1",
                session_id,
            )
        if not row:
            return None
        return Session(
            session_id=row["session_id"],
            user_id=row["user_id"],
            username=row["username"],
            node_id=row["node_id"],
            created_at=row["created_at"],
            expires_at=row["expires_at"],
            last_seen=row["last_seen"],
            ws_connected=row["ws_connected"],
            metadata=row["metadata"],
        )

    async def validate_session(self, session_id: str) -> Optional[Session]:
        """Validate and touch a session. Returns Session if valid, None if expired/missing."""
        session = await self.get_session(session_id)
        if not session:
            return None
        if session.is_expired():
            await self.destroy_session(session_id)
            return None
        # Touch last_seen
        now = time.time()
        async with self.pool.acquire() as conn:
            await conn.execute(
                "UPDATE mesh_sessions SET last_seen = $1 WHERE session_id = $2",
                now, session_id,
            )
        session.last_seen = now
        return session

    async def destroy_session(self, session_id: str) -> bool:
        """Delete a session from PG."""
        async with self.pool.acquire() as conn:
            result = await conn.execute(
                "DELETE FROM mesh_sessions WHERE session_id = $1",
                session_id,
            )
        deleted = result.endswith("1")
        if deleted:
            log.info("Destroyed session %s", session_id[:12])
        return deleted

    async def set_ws_connected(self, session_id: str, connected: bool) -> None:
        """Update WS connection state — visible to all nodes."""
        async with self.pool.acquire() as conn:
            await conn.execute(
                "UPDATE mesh_sessions SET ws_connected = $1, last_seen = $2 "
                "WHERE session_id = $3",
                connected, time.time(), session_id,
            )

    async def get_online_sessions(self) -> List[Session]:
        """Get all sessions with active WS connections (mesh-wide)."""
        now = time.time()
        async with self.pool.acquire() as conn:
            rows = await conn.fetch(
                "SELECT session_id, user_id, username, node_id, created_at, "
                "       expires_at, last_seen, ws_connected, metadata::text "
                "FROM mesh_sessions "
                "WHERE ws_connected = TRUE AND expires_at > $1 "
                "ORDER BY username",
                now,
            )
        return [
            Session(
                session_id=r["session_id"],
                user_id=r["user_id"],
                username=r["username"],
                node_id=r["node_id"],
                created_at=r["created_at"],
                expires_at=r["expires_at"],
                last_seen=r["last_seen"],
                ws_connected=r["ws_connected"],
                metadata=r["metadata"],
            )
            for r in rows
        ]

    async def get_online_users(self) -> List[Dict[str, Any]]:
        """Get distinct online users (mesh-wide)."""
        sessions = await self.get_online_sessions()
        seen: Dict[str, Dict[str, Any]] = {}
        for s in sessions:
            if s.user_id not in seen:
                seen[s.user_id] = {
                    "user_id": s.user_id,
                    "username": s.username,
                    "nodes": [],
                    "session_count": 0,
                }
            seen[s.user_id]["nodes"].append(s.node_id)
            seen[s.user_id]["session_count"] += 1
        return list(seen.values())

    async def get_sessions_for_node(self, node_id: str) -> List[Session]:
        """Get all sessions belonging to a specific node."""
        async with self.pool.acquire() as conn:
            rows = await conn.fetch(
                "SELECT session_id, user_id, username, node_id, created_at, "
                "       expires_at, last_seen, ws_connected, metadata::text "
                "FROM mesh_sessions WHERE node_id = $1 AND expires_at > $2",
                node_id, time.time(),
            )
        return [
            Session(
                session_id=r["session_id"],
                user_id=r["user_id"],
                username=r["username"],
                node_id=r["node_id"],
                created_at=r["created_at"],
                expires_at=r["expires_at"],
                last_seen=r["last_seen"],
                ws_connected=r["ws_connected"],
                metadata=r["metadata"],
            )
            for r in rows
        ]

    async def cleanup_expired(self) -> int:
        """Remove expired sessions. Returns count deleted."""
        now = time.time()
        async with self.pool.acquire() as conn:
            result = await conn.execute(
                "DELETE FROM mesh_sessions WHERE expires_at < $1",
                now,
            )
        count = int(result.split()[-1]) if result else 0
        if count:
            log.info("Cleaned up %d expired sessions", count)
        return count

    async def update_node_heartbeat(self, node_id: str, metadata: Optional[Dict] = None) -> None:
        """Upsert node heartbeat."""
        async with self.pool.acquire() as conn:
            await conn.execute(
                "INSERT INTO mesh_node_heartbeats (node_id, last_heartbeat, metadata) "
                "VALUES ($1, $2, $3::jsonb) "
                "ON CONFLICT (node_id) DO UPDATE SET "
                "  last_heartbeat = EXCLUDED.last_heartbeat, "
                "  metadata = EXCLUDED.metadata",
                node_id, time.time(), json.dumps(metadata or {}),
            )

    async def get_active_nodes(self, max_age: float = 60.0) -> List[Dict[str, Any]]:
        """Get nodes that have sent heartbeat within max_age seconds."""
        cutoff = time.time() - max_age
        async with self.pool.acquire() as conn:
            rows = await conn.fetch(
                "SELECT node_id, last_heartbeat, metadata::text "
                "FROM mesh_node_heartbeats WHERE last_heartbeat > $1",
                cutoff,
            )
        return [
            {
                "node_id": r["node_id"],
                "last_heartbeat": r["last_heartbeat"],
                "metadata": json.loads(r["metadata"]) if r["metadata"] else {},
            }
            for r in rows
        ]

    # -- Password helpers -------------------------------------------------

    @staticmethod
    def _hash_password(password: str) -> str:
        salt = secrets.token_hex(16)
        h = hashlib.pbkdf2_hmac("sha256", password.encode(), salt.encode(), 100_000)
        return f"pbkdf2_sha256${salt}${h.hex()}"

    @staticmethod
    def _verify_password(password: str, stored: str) -> bool:
        try:
            algo, salt, hash_hex = stored.split("$", 2)
        except ValueError:
            return False
        if algo != "pbkdf2_sha256":
            return False
        h = hashlib.pbkdf2_hmac("sha256", password.encode(), salt.encode(), 100_000)
        return secrets.compare_digest(h.hex(), hash_hex)


# ---------------------------------------------------------------------------
# SQLite → PG migration
# ---------------------------------------------------------------------------

async def migrate_sqlite_to_pg(store: PgSessionStore, sqlite_path: Path) -> int:
    """
    Read existing sessions from per-node SQLite and import into PG.
    Returns number of sessions migrated.
    """
    if not sqlite_path.exists():
        log.info("SQLite DB not found at %s — skipping migration", sqlite_path)
        return 0

    log.info("Migrating sessions from SQLite (%s) to PG...", sqlite_path)
    count = 0

    conn_sqlite = sqlite3.connect(str(sqlite_path))
    conn_sqlite.row_factory = sqlite3.Row

    # Try to read users
    try:
        cursor = conn_sqlite.execute(
            "SELECT user_id, username, password_hash, created_at FROM mesh_users"
        )
        users = cursor.fetchall()
        for u in users:
            try:
                async with store.pool.acquire() as pg_conn:
                    await pg_conn.execute(
                        "INSERT INTO mesh_users (user_id, username, password_hash, created_at) "
                        "VALUES ($1, $2, $3, $4) ON CONFLICT (user_id) DO NOTHING",
                        u["user_id"], u["username"], u["password_hash"], u["created_at"],
                    )
            except Exception as e:
                log.warning("Could not migrate user '%s': %s", u["username"], e)
        log.info("Migrated %d users from SQLite", len(users))
    except sqlite3.OperationalError:
        log.info("No mesh_users table in SQLite — creating fresh")

    # Try to read sessions
    try:
        cursor = conn_sqlite.execute(
            "SELECT session_id, user_id, username, node_id, created_at, "
            "       expires_at, last_seen, ws_connected, metadata "
            "FROM mesh_sessions"
        )
        sessions = cursor.fetchall()
        for s in sessions:
            try:
                async with store.pool.acquire() as pg_conn:
                    await pg_conn.execute(
                        "INSERT INTO mesh_sessions "
                        "(session_id, user_id, username, node_id, created_at, "
                        " expires_at, last_seen, ws_connected, metadata) "
                        "VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9::jsonb) "
                        "ON CONFLICT (session_id) DO NOTHING",
                        s["session_id"], s["user_id"], s["username"],
                        s["node_id"] or NODE_ID, s["created_at"], s["expires_at"],
                        s["last_seen"], bool(s["ws_connected"]),
                        s["metadata"] if s["metadata"] else "{}",
                    )
                count += 1
            except Exception as e:
                log.warning("Could not migrate session %s: %s", s["session_id"][:12], e)
    except sqlite3.OperationalError:
        log.info("No mesh_sessions table in SQLite — nothing to migrate")

    conn_sqlite.close()
    log.info("Migration complete: %d sessions imported", count)
    return count


# ---------------------------------------------------------------------------
# SessionManager — high-level orchestration with WS broadcast
# ---------------------------------------------------------------------------

class SessionManager:
    """
    High-level session manager that wraps PgSessionStore and handles
    mesh-wide online status broadcasting via WebSocket fan-out.
    """

    def __init__(self, store: PgSessionStore):
        self.store = store
        # Local WS connections: session_id -> web.WebSocketResponse
        self.ws_connections: Dict[str, web.WebSocketResponse] = {}
        # Subscribed WS clients that want online-status updates
        self.status_subscribers: Set[web.WebSocketResponse] = set()
        self._cleanup_task: Optional[asyncio.Task] = None
        self._heartbeat_task: Optional[asyncio.Task] = None

    async def start(self) -> None:
        """Start background tasks."""
        self._cleanup_task = asyncio.create_task(self._cleanup_loop())
        self._heartbeat_task = asyncio.create_task(self._heartbeat_loop())
        log.info("SessionManager started (node=%s)", self.store.node_id)

    async def stop(self) -> None:
        """Stop background tasks and close all WS."""
        if self._cleanup_task:
            self._cleanup_task.cancel()
        if self._heartbeat_task:
            self._heartbeat_task.cancel()
        # Close all WS
        for ws in list(self.ws_connections.values()):
            try:
                await ws.close()
            except Exception:
                pass
        for ws in list(self.status_subscribers):
            try:
                await ws.close()
            except Exception:
                pass
        self.ws_connections.clear()
        self.status_subscribers.clear()
        log.info("SessionManager stopped")

    async def login(self, username: str, password: str) -> Optional[Session]:
        """Authenticate and create a session."""
        user_id = await self.store.verify_user(username, password)
        if not user_id:
            log.warning("Login failed for user '%s'", username)
            return None
        session = await self.store.create_session(user_id, username)
        await self._broadcast_session_update("login", session)
        return session

    async def logout(self, session_id: str) -> bool:
        """Destroy a session and broadcast."""
        session = await self.store.get_session(session_id)
        if not session:
            return False
        # Close local WS if any
        ws = self.ws_connections.pop(session_id, None)
        if ws and not ws.closed:
            await ws.close()
        await self.store.destroy_session(session_id)
        await self._broadcast_session_update("logout", session)
        return True

    async def register_ws(self, session_id: str, ws: web.WebSocketResponse) -> bool:
        """Register a WebSocket connection for a session."""
        session = await self.store.validate_session(session_id)
        if not session:
            return False
        self.ws_connections[session_id] = ws
        await self.store.set_ws_connected(session_id, True)
        await self._broadcast_session_update("ws_connect", session)
        return True

    async def unregister_ws(self, session_id: str) -> None:
        """Unregister a WebSocket connection."""
        self.ws_connections.pop(session_id, None)
        await self.store.set_ws_connected(session_id, False)
        session = await self.store.get_session(session_id)
        if session:
            await self._broadcast_session_update("ws_disconnect", session)

    async def subscribe_status(self, ws: web.WebSocketResponse) -> None:
        """Subscribe a WS client to receive online-status updates."""
        self.status_subscribers.add(ws)
        # Send current online state immediately
        online = await self.store.get_online_users()
        await self._safe_send(ws, {
            "type": "online_status",
            "action": "snapshot",
            "online_users": online,
            "node_id": self.store.node_id,
            "timestamp": time.time(),
        })

    def unsubscribe_status(self, ws: web.WebSocketResponse) -> None:
        self.status_subscribers.discard(ws)

    async def _broadcast_session_update(
        self, action: str, session: Session
    ) -> None:
        """
        Broadcast a session update to all subscribed WS clients.
        Because sessions are in PG, every node sees the same state.
        """
        online = await self.store.get_online_users()
        message = {
            "type": "online_status",
            "action": action,
            "session": session.to_dict(),
            "online_users": online,
            "node_id": self.store.node_id,
            "timestamp": time.time(),
        }
        # Fan-out to local subscribers
        dead: List[web.WebSocketResponse] = []
        for ws in self.status_subscribers:
            if ws.closed:
                dead.append(ws)
                continue
            await self._safe_send(ws, message)
        for ws in dead:
            self.status_subscribers.discard(ws)

    async def _safe_send(self, ws: web.WebSocketResponse, msg: Dict) -> None:
        try:
            await ws.send_json(msg)
        except Exception as e:
            log.debug("WS send failed: %s", e)

    async def _cleanup_loop(self) -> None:
        """Periodically clean up expired sessions."""
        while True:
            try:
                await asyncio.sleep(300)  # every 5 minutes
                await self.store.cleanup_expired()
            except asyncio.CancelledError:
                break
            except Exception as e:
                log.error("Cleanup error: %s", e)

    async def _heartbeat_loop(self) -> None:
        """Periodically send node heartbeat to PG."""
        while True:
            try:
                await asyncio.sleep(15)
                await self.store.update_node_heartbeat(
                    self.store.node_id,
                    {"ws_count": len(self.ws_connections)},
                )
            except asyncio.CancelledError:
                break
            except Exception as e:
                log.error("Heartbeat error: %s", e)


